@use 'variables' as *;
@use 'mixins' as *;

// Lista wartoÅ›ci
$xl-min-values: (590, 580, 210, 150, 140, 130, 126, 123, 121, 120, 110, 104, 100, 94, 90, 80, 70, 66, 60, 57, 50, 40, 33, 30, 28, 24, 23, 22, 18);
$scale-factors: (
    xl-max: calc(1 / 1.25),
    // 75% wartoÅ›ci poprzedniej
    md-max: calc(1 / 1.5625),
    // 75% wartoÅ›ci poprzedniej
    sm-max: calc(1 / 1.953125) // 75% wartoÅ›ci poprzedniej,,,,
);

// Tworzenie mapy spacing-values
$spacing-values: ();

@each $size in $xl-min-values {
    $breakpoints: (
        xl-min: #{$size}px,
    );

    @each $bp, $factor in $scale-factors {
        // Warunki dla wykluczania md-max i sm-max
        @if not(
            ($size == 30 or $size == 40) and
                ($bp == md-max or $bp == sm-max) or
                ($size == 50 or $size == 60) and
                ($bp == sm-max)
        )
        {
            $breakpoints: map-merge(
                $breakpoints,
                (
                    $bp: round($size * $factor) + px,
                )
            );
        }
    }

    $spacing-values: map-merge(
        $spacing-values,
        (
            $size: $breakpoints,
        )
    );
}

// Mixiny do generowania klas
@mixin generate-spacing($property) {
    @each $size, $breakpoints in $spacing-values {
        %#{$property}-#{$size} {
            @each $bp, $value in $breakpoints {
                @if $bp == xl-min {
                    @include media($breakpoint-xl, min) {
                        #{$property}: $value;
                    }
                } @else if $bp == xl-max {
                    @include media($breakpoint-xl, max) {
                        #{$property}: $value;
                    }
                } @else if $bp == md-max {
                    @include media($breakpoint-md, max) {
                        #{$property}: $value;
                    }
                } @else if $bp == sm-max {
                    @include media($breakpoint-sm, max) {
                        #{$property}: $value;
                    }
                }
            }
        }
    }
}

// Mixin dla osi x i y
@mixin generate-axis-spacing($axis) {
    @each $size, $breakpoints in $spacing-values {
        @if $axis == "padding-y" {
            %#{$axis}-#{$size} {
                @each $bp, $value in $breakpoints {
                    @if $bp == xl-min {
                        @include media($breakpoint-xl, min) {
                            padding-top: $value;
                            padding-bottom: $value;
                        }
                    } @else if $bp == xl-max {
                        @include media($breakpoint-xl, max) {
                            padding-top: $value;
                            padding-bottom: $value;
                        }
                    } @else if $bp == md-max {
                        @include media($breakpoint-md, max) {
                            padding-top: $value;
                            padding-bottom: $value;
                        }
                    } @else if $bp == sm-max {
                        @include media($breakpoint-sm, max) {
                            padding-top: $value;
                            padding-bottom: $value;
                        }
                    }
                }
            }
        } @else if $axis == "padding-x" {
            %#{$axis}-#{$size} {
                @each $bp, $value in $breakpoints {
                    @if $bp == xl-min {
                        @include media($breakpoint-xl, min) {
                            padding-left: $value;
                            padding-right: $value;
                        }
                    } @else if $bp == xl-max {
                        @include media($breakpoint-xl, max) {
                            padding-left: $value;
                            padding-right: $value;
                        }
                    } @else if $bp == md-max {
                        @include media($breakpoint-md, max) {
                            padding-left: $value;
                            padding-right: $value;
                        }
                    } @else if $bp == sm-max {
                        @include media($breakpoint-sm, max) {
                            padding-left: $value;
                            padding-right: $value;
                        }
                    }
                }
            }
        } @else if $axis == "margin-y" {
            %#{$axis}-#{$size} {
                @each $bp, $value in $breakpoints {
                    @if $bp == xl-min {
                        @include media($breakpoint-xl, min) {
                            margin-top: $value;
                            margin-bottom: $value;
                        }
                    } @else if $bp == xl-max {
                        @include media($breakpoint-xl, max) {
                            margin-top: $value;
                            margin-bottom: $value;
                        }
                    } @else if $bp == md-max {
                        @include media($breakpoint-md, max) {
                            margin-top: $value;
                            margin-bottom: $value;
                        }
                    } @else if $bp == sm-max {
                        @include media($breakpoint-sm, max) {
                            margin-top: $value;
                            margin-bottom: $value;
                        }
                    }
                }
            }
        } @else if $axis == "margin-x" {
            %#{$axis}-#{$size} {
                @each $bp, $value in $breakpoints {
                    @if $bp == xl-min {
                        @include media($breakpoint-xl, min) {
                            margin-left: $value;
                            margin-right: $value;
                        }
                    } @else if $bp == xl-max {
                        @include media($breakpoint-xl, max) {
                            margin-left: $value;
                            margin-right: $value;
                        }
                    } @else if $bp == md-max {
                        @include media($breakpoint-md, max) {
                            margin-left: $value;
                            margin-right: $value;
                        }
                    } @else if $bp == sm-max {
                        @include media($breakpoint-sm, max) {
                            margin-left: $value;
                            margin-right: $value;
                        }
                    }
                }
            }
        }
    }
}

